INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64140586', 64140586, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS PARIWISATA DAN EKONOMI KREATIF', 'Penyediaan Jasa Tenaga Ahli Pengawas Pemeliharaan Gedung A', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 21000000, 'July 2026', 'APBD', 1, 1, '1 Paket', 'Ruang lingkup pekerjaan: 1. Melaksanakan review terhadap desain yang ada, serta alternatif desain bila dipandang perlu, disesuaikandengan kondisi dan kebutuhan real di lapangan. 2. Mengecek pengukuran yang dilaksanakan oleh penyedia jasa konstruksi 3. menganalisis bahan-bahan yang akan dipakai 4. Memberikan arahan teknis sebelum pelaksanaan pekerjaan di lapangan dilakukan. 5. Melaksanakan inspeksi kegiatan pelaksanaan pekerjaan agar pelaksanaan teknis maupun administrasi teknis yang dilakukan secara berkelanjutan sampai dengan serah terima pekerjaan. 6. Mengawasi dan melakukan pengendalian atas kualitas dan kuantitas dari bahan atau komponen material, peralatan dan perlengkapan selama pekerjaan pelaksanaan di lapangan. 7. Mengawasi dan mengontrol kemajuan pelaksanaan dan mengambil tindakan yang tepat dan cepat, agar batas waktu pelaksanaan minimal sesuai dengan jadwal yangtelah ditetapkan. 8. Mengawasi dan mengontrol metode pelaksanaan pekerjaan agar sesuai dengan pedoman teknis pelaksanaan pekerjaan. 9. Memberikan rekomendasi teknis tentang penambahan atau pengurangan pekerjaan yang dapat mempengaruhi mutu, biaya dan waktu pekerjaan serta berpengaruh pada ketentuan kontrak, untuk mendapatkan persetujuan dari Pengguna Jasa / Kuasa Pengguna Anggaran / Pelaksana Kegiatan / Pejabat Pembuat Komitmen 10. Melaporkan semua kegiatan pengawasan dalam laporan mingguan, laporan bulanan dan laporan akhir pekerjaan 11. Menerima dan memverifikasi Berita Acara sehubungan dengan penyelesaian pekerjaan di lapangan, serta untuk keperluan pembayaran progres pekerjaan 12 Memeriksa dan memverifikasi daftar volume dan nilai pekerjaan, serta penambahan atau pengurangan pekerjaan guna keperluan pembayaran. 13. Memeriksa dan memverifikasi laporan mingguan dan bulanan, Berita Acara Kemajuan Pekerjaan, Berita Acara Penyerahan Pertama dan Kedua serta formulir-formulir lainnya yang diperlukan untuk kebutuhan dokumen laporan kegiatan', 'Tenaga Ahli Muda Spesifikasi: Tenaga Ahli Jasa Konsultansi Konstruksi (Pendidikan S1- Pengalaman 2 Tahun)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1353700);
