INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64160906', 64160906, 'analyze_legacy', 'Kota Tangerang', 'kabkota', 'DINAS PEKERJAAN UMUM DAN PENATAAN RUANG', 'Jasa Konsultansi Perencanaan Teknis Tata Air III', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Banten, Tangerang (Kota)', 19047000, 'May 2026', 'APBD', 1, 1, '1', 'Tenaga Ahli Sumber Daya Air: - Menyusun persyaratan dan membuat laporan Sistem Manajemen Mutu (SMM) dan Sistem Manajemen Kesehatan dan Keselamtan Kerja Lingkungan (SMK3L). - Menyusun Rencana Survei dan Investigasi Drainase serta Bangunan Pengendali Banjir lainnya sesuai Kerangka Acuan Kerja. - Memeriksa data hasil survei dan hasil pengumpulan data/informasi yang diperlukan untuk sistem tata air. - Menyiapkan data hidrologi. - Mempelajari dan menguasai data terdahulu untuk daerah yang akan diselidiki. - Melakukan analisis menggunakan program aplikasi yang mampu melakukan analisa hidrologi dan hidrolika secara 2 Dimensi dan membuat peta banjir / flood map. - Analisis menghasilkan simulasi banjir dengan memperhitungkan catchment area dan beberapa variasi Q hujan rencana serta beberapa alternatif penyusunan pompa atau bangunan pengendali banjir lainnya. - Banyaknya alternatif / kondisi yang dilakukan dalam simulasi ditentukan pada saat proses pembahasan. - Melakukan perhitungan struktur saluran drainase, serta bangunan pengendali banjir lainnya. - Membuat laporan dan rekomendasi hasil perhitungan hidrologi dan hidrolika. - Menyusun spesifikasi. - Menyusun Rencana teknis pekerjaan drainase dan bangunan pengendali banjir lainnya. - Membuat Rencana Operasi dan Pemeliharaan. - Melakukan pengarahan dan pemeriksaan gambar desain. Tenaga Ahli Geodesi: - Menyiapkan data pengukuran. - Mempelajari data terdahulu untuk daerah yang akan diselidiki. - Membuat perencanaan penyelidikan pengukuran. - Melakukan analisa hasil pengukuran. - Membuat laporan dan rekomendasi hasil pengukuran. Tenaga Ahli Geoteknik: - Menyiapkan data geoteknik - Mempelajari dan menguasai data terdahulu untuk daerah yang akan diselidiki - Membuat perencanaan penyelidikan geoteknik - Melakukan analisa hasil penyelidikan geoteknik - Membuat laporan dan rekomendasi hasil penyelidikan geoteknik', 'Tenaga Ahli Teknik Sumber Daya Air/Geodesi/Geoteknik Ahli Muda S1 Pengalaman 3 Tahun', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1357061);
